@Composable fun PlannerScreen(m:DressModel,n:Navigator){Page{Heading("Less packing. More possibility.","Go beautifully\nprepared.");Box(Modifier.clip(RoundedCornerShape(28.dp))){EditorialPhoto("couple_dry_7_0_3",230.dp);Box(Modifier.matchParentSize().background(Brush.verticalGradient(listOf(Color.Transparent,Color.Black.copy(alpha=.6f)))));Column(Modifier.align(Alignment.BottomStart).padding(22.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("THE ART OF THE GETAWAY",fontSize=9.sp,letterSpacing=2.sp,color=Color.White);EditorialText("A forecast. A capsule.\nA lighter suitcase.",30,color=Color.White)}};Body("Choose your destination and dates. Build a packing list from its actual weather, including the warmest, coldest and wettest parts of your trip.");Action("Plan a new trip",Modifier.fillMaxWidth(),primary=true,icon=Icons.Outlined.Add){n.newTrip(m,false)};StudioLink("The Pro travel capsule","Daily combinations with pieces from your wardrobe.",Icons.Outlined.AutoAwesome){n.open("capsules")};if(m.p.trips.isEmpty())GlassCard{EditorialText("Your next chapter",27);Body("Trips and packing lists stay on this device. Plan up to eight days ahead.")};m.p.trips.forEach{trip->StudioLink(trip.city.name,"${m.dayTitle(trip.start,"MMM d")} – ${m.dayTitle(trip.end,"MMM d")}\n${trip.checked.size} of ${trip.items.size} packed",Icons.Outlined.Flight){n.open("trip",trip.id)}}}}
@Composable fun CapsuleHomeScreen(m:DressModel,n:Navigator){Page(maxWidth=760.dp){Heading("Considered pieces. More combinations.","Your travel\ncapsule.");EditorialPhoto("couple_dry_6_1_1",240.dp);Body("Pack for the coldest, warmest, wettest and windiest parts of your trip. We’ll look for pieces you own and favor suitable pieces that can work again.");Action("Build a capsule",Modifier.fillMaxWidth(),primary=true,icon=Icons.Outlined.Add){n.newTrip(m,true)};if(m.p.capsules.isEmpty())Caption("Add wardrobe pieces first for personal matches, or start with a suggested capsule.");m.p.capsules.forEach{c->StudioLink(c.city.name,"${c.plan.days.size} days · ${c.plan.pieces.size} clothing pieces · ${c.plan.ownedCount} from your wardrobe",Icons.Outlined.Luggage){n.open("capsule",c.id)}}}}
@Composable fun NewTripScreen(m:DressModel,n:Navigator,capsule:Boolean){var busy by rememberSaveable{mutableStateOf(false)};var error by rememberSaveable{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();val context=LocalContext.current
    fun pick(start:Boolean) {
        val date=LocalDate.parse(if(start)n.tripStart else n.tripEnd)
        val zone=ZoneId.of((n.tripCity?:m.p.city).zone);val today=LocalDate.now(zone)
        DatePickerDialog(context,{_,year,month,day->val chosen=LocalDate.of(year,month+1,day).toString();if(start){n.tripStart=chosen;if(n.tripEnd<chosen)n.tripEnd=chosen}else n.tripEnd=chosen},date.year,date.monthValue-1,date.dayOfMonth).apply{datePicker.minDate=(if(start)today else LocalDate.parse(n.tripStart)).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();datePicker.maxDate=today.plusDays(8).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()}.show()
    }
    Page{SectionLabel(if(capsule)"Destination"else"Your destination");FormCard{FormRow(n.tripCity?.name?:if(capsule)m.p.city.name else"Choose a destination",icon=Icons.Outlined.Place){n.open("locations","tripDestination")}};SectionLabel("Travel dates");FormCard{FormRow("Departure",m.dayTitle(n.tripStart,"MMM d, yyyy")){pick(true)};DividerLine();FormRow("Return",m.dayTitle(n.tripEnd,"MMM d, yyyy")){pick(false)};if(capsule){DividerLine();Choice("Main occasion",Occasion.entries.map{it.label},n.tripOccasion.label){n.tripOccasion=Occasion.valueOf(it)}}};Caption(if(capsule)"Capsules use available forecasts within eight days. Your wardrobe’s comfort ranges and rain-ready choices determine personal matches. Pack fresh base layers and essentials for every day; repeated pieces aren’t a laundry plan."else"Lists use available forecasts, not seasonal guesses. Plan within eight days of today. Dates refer to the destination’s local calendar.");Action(if(busy)if(capsule)"Considering the forecast…"else"Checking destination weather…"else if(capsule)"Create my capsule"else"Create my packing list",Modifier.fillMaxWidth(),enabled=!busy&&(capsule||n.tripCity!=null),primary=true){busy=true;error=null;scope.launch{try{m.makeTrip(n.tripCity?:m.p.city,n.tripStart,n.tripEnd,capsule,n.tripOccasion);n.back()}catch(e:Exception){error=e.message?:"The destination forecast couldn’t be loaded. Try again."}finally{busy=false}}};error?.let{Caption(it,color=Color(0xFFAD3838))}}
}
@Composable fun PackingScreen(m:DressModel,n:Navigator,id:String){val trip=m.p.trips.firstOrNull{it.id==id}?:return;val c=LocalContext.current;var deletion by remember{mutableStateOf(false)}
    Page{Heading("Your capsule wardrobe",trip.city.name);Text("${trip.checked.size} of ${trip.items.size} packed",color=Olive);LinearProgressIndicator(progress={trip.checked.size.toFloat()/trip.items.size.coerceAtLeast(1)},modifier=Modifier.fillMaxWidth(),color=Olive);SectionLabel("Pack thoughtfully");FormCard{trip.items.forEach{item->ChecklistRow(item,null,item in trip.checked){m.edit{p->p.copy(trips=p.trips.map{t->if(t.id==id)t.copy(checked=if(item in t.checked)t.checked-item else t.checked+item)else t})}};if(item!=trip.items.last())DividerLine()}};Action("Share packing list",Modifier.fillMaxWidth(),icon=Icons.Outlined.IosShare){shareText(c,"Packing for ${trip.city.name}\n"+trip.items.joinToString("\n"){"• $it"})};TextButton({deletion=true}){Text("Delete trip",color=Color(0xFFAD3838))}}
    if(deletion)AlertDialog(onDismissRequest={deletion=false},title={Text("Delete this trip?")},confirmButton={TextButton({m.edit{it.copy(trips=it.trips.filterNot{t->t.id==id})};n.back()}){Text("Delete trip")}},dismissButton={TextButton({deletion=false}){Text("Cancel")}})
}
@Composable fun ChecklistRow(name:String,detail:String?,checked:Boolean,onToggle:()->Unit){Row(Modifier.fillMaxWidth().clickable(onClick=onToggle).padding(vertical=9.dp),horizontalArrangement=Arrangement.spacedBy(14.dp),verticalAlignment=Alignment.Top){Icon(if(checked)Icons.Outlined.CheckCircle else Icons.Outlined.RadioButtonUnchecked,null,Modifier.size(23.dp),tint=Olive);Column(verticalArrangement=Arrangement.spacedBy(5.dp)){Text(name,color=Ink);if(detail!=null)Caption(detail)}}}
@Composable fun CapsuleDetailScreen(m:DressModel,n:Navigator,id:String){val c=m.p.capsules.firstOrNull{it.id==id}?:return;val context=LocalContext.current;var deletion by remember{mutableStateOf(false)}
    fun toggle(item:String){m.edit{it.copy(capsules=it.capsules.map{s->if(s.id==id)s.copy(checked=if(item in s.checked)s.checked-item else s.checked+item)else s})}}
    Page{Heading("${c.plan.days.size} days · ${c.plan.pieces.size} considered pieces",c.city.name);Body("${c.plan.ownedCount} pieces from your wardrobe. Other pieces are suggestions to add or adapt.");SectionLabel("The capsule");FormCard{c.plan.pieces.forEachIndexed{i,piece->ChecklistRow(piece.name,"${if(piece.garmentID==null)"Suggested"else"You own this"} · ${piece.daysUsed} ${if(piece.daysUsed==1)"day"else"days"}",piece.name in c.checked){toggle(piece.name)};if(i<c.plan.pieces.lastIndex)DividerLine()}};SectionLabel("Bring as well");FormCard{c.plan.bring.forEach{item->ChecklistRow(item,null,item in c.checked){toggle(item)}}};SectionLabel("The daily combinations");FormCard{c.plan.days.forEach{day->Column(verticalArrangement=Arrangement.spacedBy(12.dp)){EditorialText(m.dayTitle(day.date),25);Caption(day.pieces.joinToString(" · "))};DividerLine()}};Action("Share capsule checklist",Modifier.fillMaxWidth(),icon=Icons.Outlined.IosShare){shareText(context,"Capsule for ${c.city.name}\n"+c.plan.checklist.joinToString("\n"){"• $it"})};TextButton({deletion=true}){Text("Delete capsule",color=Color(0xFFAD3838))}}
    if(deletion)AlertDialog(onDismissRequest={deletion=false},title={Text("Delete this capsule?")},confirmButton={TextButton({m.edit{it.copy(capsules=it.capsules.filterNot{s->s.id==id})};n.back()}){Text("Delete capsule")}},dismissButton={TextButton({deletion=false}){Text("Cancel")}})
}
